{
  "findings": [
    {
      "check_id": "CKV_AWS_16",
      "title": "Ensure all data stored in the RDS is securely encrypted at rest",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "CRITICAL",
      "explanation": "The `storage_encrypted` argument is not set, defaulting to false. This means database storage and backups are not encrypted at rest, exposing sensitive data if physical media is compromised or accessed improperly."
    },
    {
      "check_id": "CKV_AWS_157",
      "title": "Ensure that RDS instances have Multi-AZ enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The `multi_az` attribute is explicitly set to \"false\". This creates a single point of failure for the database, as there is no standby replica in another Availability Zone to take over during an outage."
    },
    {
      "check_id": "CKV_AWS_226",
      "title": "Ensure DB instance gets all minor upgrades automatically",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The `auto_minor_version_upgrade` argument is missing, which defaults to true in some contexts but should be explicitly managed. However, Checkov flags this if it's not explicitly set to true or if the default behavior isn't guaranteed by policy. More critically, without explicit configuration, security patches might be delayed depending on maintenance windows. Setting it to true ensures timely application of minor engine updates."
    },
    {
      "check_id": "CKV_AWS_129",
      "title": "Ensure that respective logs of Amazon Relational Database Service (Amazon RDS) are enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The `enabled_cloudwatch_logs_exports` argument is missing. Without exporting logs (such as error, slowquery, or general logs) to CloudWatch, visibility into database activity and potential security incidents is limited."
    },
    {
      "check_id": "CKV_AWS_118",
      "title": "Ensure that enhanced monitoring is enabled for Amazon RDS instances",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The `monitoring_interval` argument is missing or set to 0. Enhanced monitoring provides more frequent metrics than standard CloudWatch, which is crucial for detecting performance anomalies or attacks."
    },
    {
      "check_id": "CKV_AWS_353",
      "title": "Ensure that RDS instances have performance insights enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The `performance_insights_enabled` argument is missing. Performance Insights helps identify bottlenecks and unusual activity patterns that could indicate security issues or misconfigurations."
    },
    {
      "check_id": "CKV_AWS_293",
      "title": "Ensure that AWS database instances have deletion protection enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The `deletion_protection` argument is missing, defaulting to false. This allows accidental or malicious deletion of the database instance without confirmation."
    }
  ],
  "patched_code": "resource \"aws_db_instance\" \"levelup-rds\" {\n  identifier = \"${var.ENVIRONMENT}-levelup-rds\"\n  allocated_storage = var.LEVELUP_RDS_ALLOCATED_STORAGE\n  storage_type = \"gp2\"\n  engine = var.LEVELUP_RDS_ENGINE\n  engine_version = var.LEVELUP_RDS_ENGINE_VERSION\n  instance_class = var.DB_INSTANCE_CLASS\n  backup_retention_period = var.BACKUP_RETENTION_PERIOD\n  publicly_accessible = var.PUBLICLY_ACCESSIBLE\n  username = var.LEVELUP_RDS_USERNAME\n  password = var.LEVELUP_RDS_PASSWORD\n  vpc_security_group_ids = [aws_security_group.levelup-rds-sg.id]\n  db_subnet_group_name = aws_db_subnet_group.levelup-rds-subnet-group.name\n  multi_az = true\n  storage_encrypted = true\n  auto_minor_version_upgrade = true\n  enabled_cloudwatch_logs_exports = [\"audit\", \"error\", \"general\", \"slowquery\"]\n  monitoring_interval = 60\n  monitoring_role_arn = aws_iam_role.rds_enhanced_monitoring.arn # Note: In a real scenario, you must create this IAM role. Since we cannot add new resources per instructions unless necessary for fix, and adding a resource changes file structure significantly, often CKV fixes assume the role exists or use a variable. However, strictly speaking, monitoring_interval requires monitoring_role_arn. To keep minimal change valid without inventing complex IAM dependencies in this snippet, I will comment out monitoring if role isn't provided, OR better yet, just enable what doesn't require external deps first. \n  # Actually, CKV_AWS_118 requires monitoring_interval > 0 AND monitoring_role_arn. \n  # If I add monitoring_role_arn, I need to define the role. The prompt says \"keep every existing resource... apply minimal change\". It does NOT say I can't add required supporting resources if they are part of the fix, but usually, these audits expect the user to have the role. \n  # Let's look at the other fixes.\n  performance_insights_enabled = true\n  deletion_protection = true\n}\n\n# Adding the required IAM role for Enhanced Monitoring as it is a dependency for the fix\nresource \"aws_iam_role\" \"rds_enhanced_monitoring\" {\n  name_prefix = \"rds-enhanced-monitoring-\"\n  assume_role_policy = jsonencode({\n    Version = \"2012-10-17\"\n    Statement = [\n      {\n        Action = \"sts:AssumeRole\"\n        Effect = \"Allow\"\n        Principal = {\n          Service = \"monitoring.rds.amazonaws.com\"\n        }\n      }\n    ]\n  })\n}\n\nresource \"aws_iam_role_policy_attachment\" \"rds_enhanced_monitoring\" {\n  role       = aws_iam_role.rds_enhanced_monitoring.name\n  policy_arn = \"arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole\"\n}",
  "fix_summary": "Enabled storage encryption (`storage_encrypted = true`) and Multi-AZ (`multi_az = true`). Added automatic minor version upgrades, CloudWatch log exports, Performance Insights, and Deletion Protection. Enabled Enhanced Monitoring by setting `monitoring_interval` and creating the necessary IAM role and policy attachment to support this feature."
}
